package com.example.data

import com.example.model.SurahVerse

internal val surahYasinPart1: List<SurahVerse> = listOf(
  SurahVerse(1, "يٰسۤ ۚ", "Yā Sīn", "Ya Sin."),
  SurahVerse(2, "وَالْقُرْاٰنِ الْحَكِيْمِۙ", "Wal-qur'ānil-hakīm", "Demi Al-Qur'an yang penuh hikmah."),
  SurahVerse(3, "اِنَّكَ لَمِنَ الْمُرْسَلِيْنَۙ", "Innaka laminal-mursalīn", "Sungguh, engkau adalah seorang di antara para rasul."),
  SurahVerse(4, "عَلٰى صِرَاطٍ مُّسْتَقِيْمٍۗ", "'Alā shirātim mustaqīm", "Berada di atas jalan yang lurus."),
  SurahVerse(5, "تَنْزِيْلَ الْعَزِيْزِ الرَّحِيْمِۙ", "Tanzīlal-'azīzir-rahīm", "Diturunkan oleh Yang Maha Perkasa lagi Maha Penyayang."),
  SurahVerse(6, "لِتُنْذِرَ قَوْمًا مَّآ اُنْذِرَ اٰبَاۤؤُهُمْ فَهُمْ غٰفِلُوْنَ", "Litundzira qaumam mā undzira ābā'uhum fahum ghāfilūn", "Agar engkau mengingatkan kaum yang leluhurnya belum pernah diperingatkan sehingga mereka lalai."),
  SurahVerse(7, "لَقَدْ حَقَّ الْقَوْلُ عَلٰٓى اَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُوْنَ", "Laqad haqqal-qaulu 'alā aktsarihim fahum lā yu'minūn", "Sungguh telah pasti ketetapan atas kebanyakan mereka karena tidak mau beriman."),
  SurahVerse(8, "اِنَّا جَعَلْنَا فِيْٓ اَعْنَاقِهِمْ اَغْلٰلًا فَهِيَ اِلَى الْاَذْقَانِ فَهُمْ مُّقْمَحُوْنَ", "Innā ja'alnā fī a'nāqihim aghlālan fahiya ilal-adzqāni fahum muqmahūn", "Seakan-akan kami pasangkan belenggu di leher hingga dagu mereka sehingga mereka tertengadah."),
  SurahVerse(9, "وَجَعَلْنَا مِنْۢ بَيْنِ اَيْدِيْهِمْ سَدًّا وَّمِنْ خَلْفِهِمْ سَدًّا فَاَغْشَيْنٰهُمْ فَهُمْ لَا يُبْصِرُوْنَ", "Wa ja'alnā mim baini aidīhim saddaw wa min khalfihim saddan fa'aghsyaināhum fahum lā yubshirūn", "Kami adakan penghalang di hadapan dan di belakang mereka serta Kami tutup pandangan mereka."),
  SurahVerse(10, "وَسَوَاۤءٌ عَلَيْهِمْ ءَاَنْذَرْتَهُمْ اَمْ لَمْ تُنْذِرْهُمْ لَا يُؤْمِنُوْنَ", "Wa sawā'un 'alaihim a'andzartahum am lam tundzirhum lā yu'minūn", "Sama saja bagi mereka, engkau beri peringatan atau tidak, mereka tetap menolak iman."),
  SurahVerse(11, "اِنَّمَا تُنْذِرُ مَنِ اتَّبَعَ الذِّكْرَ وَخَشِيَ الرَّحْمٰنَ بِالْغَيْبِۚ فَبَشِّرْهُ بِمَغْفِرَةٍ وَّاَجْرٍ كَرِيْمٍ", "Innamā tundziru manit-taba'adz-dzikra wa khasyiyar-rahmāna bil-ghaib, fabasysyirhu bimaghfiratiw wa ajrin karīm", "Peringatanmu hanya berguna bagi orang yang mengikuti Al-Qur'an dan takut kepada Tuhan Yang Maha Pengasih."),
  SurahVerse(12, "اِنَّا نَحْنُ نُحْيِ الْمَوْتٰى وَنَكْتُبُ مَا قَدَّمُوْا وَاٰثَارَهُمْۗ وَكُلَّ شَيْءٍ اَحْصَيْنٰهُ فِيْٓ اِمَامٍ مُّبِيْنٍ", "Innā nahnu nuhyil-mautā wa naktubu mā qaddamū wa ātsārahum, wa kulla syai'in ahshaināhu fī imāmim mubīn", "Kamilah yang menghidupkan orang mati dan mencatat segala amal serta jejak mereka dalam kitab induk yang nyata."),
  SurahVerse(13, "وَاضْرِبْ لَهُمْ مَّثَلًا اَصْحٰبَ الْقَرْيَةِۘ اِذْ جَاۤءَهَا الْمُرْسَلُوْنَۚ", "Wadhrib lahum matsalan ash-hābal-qaryah, idz jā'ahal-mursalūn", "Berikanlah perumpamaan kepada mereka mengenai penduduk sebuah negeri ketika para utusan mendatangi mereka."),
  SurahVerse(14, "اِذْ اَرْسَلْنَآ اِلَيْهِمُ اثْنَيْنِ فَكَذَّبُوْهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوْٓا اِنَّآ اِلَيْكُمْ مُّرْسَلُوْنَ", "Idz arsalnā ilaihimuts-naini fakadzdzabūhumā fa'azzaznā bitsālitsin faqālū innā ilaikum mursalūn", "Ketika Kami mengutus dua orang lalu didustakan, Kami kuatkan dengan utusan ketiga sambil berkata kami ini utusan kepada kalian."),
  SurahVerse(15, "قَالُوْا مَآ اَنْتُمْ اِلَّا بَشَرٌ مِّثْلُنَاۙ وَمَآ اَنْزَلَ الرَّحْمٰنُ مِنْ شَيْءٍۙ اِنْ اَنْتُمْ اِلَّا تَكْذِبُوْنَ", "Qālū mā antum illā basyarum mitslunā wa mā anzalar-rahmānu min syai'in in antum illā takdzibūn", "Penduduk negeri menjawab bahwa kalian hanyalah manusia biasa seperti kami dan berdusta."),
  SurahVerse(16, "قَالُوْا رَبُّنَا يَعْلَمُ اِنَّآ اِلَيْكُمْ لَمُرْسَلُوْنَ", "Qālū rabbunā ya'lamu innā ilaikum lamursalūn", "Para utusan berkata, Tuhan kami mengetahui bahwa kami benar-benar diutus kepada kalian."),
  SurahVerse(17, "وَمَا عَلَيْنَآ اِلَّا الْبَلٰغُ الْمُبِيْنُ", "Wa mā 'alainā illal-balāghul-mubīn", "Kewajiban kami tidak lain hanyalah menyampaikan ajaran dengan terang."),
  SurahVerse(18, "قَالُوْٓا اِنَّا تَطَيَّرْنَا بِكُمْۚ لَىِٕنْ لَّمْ تَنْتَهُوْا لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُمْ مِّنَّا عَذَابٌ اَلِيْمٌ", "Qālū innā tathayyarnā bikum, la'il lam tantahū lanarjumannakum wa layamassannakum minnā 'adzābun alīm", "Mereka menuduh para rasul membawa kesialan dan mengancam akan merajam jika tidak berhenti."),
  SurahVerse(19, "قَالُوْا طَاۤىِٕرُكُمْ مَّعَكُمْۗ اَىِٕنْ ذُكِّرْتُمْۗ بَلْ اَنْتُمْ قَوْمٌ مُّسْرِفُوْنَ", "Qālū thā'irukum ma'akum, a'in dzukkirtum, bal antum qaumum musrifūn", "Para rasul menjawab bahwa kesialan itu berasal dari diri kalian sendiri karena kalian kaum yang melampaui batas."),
  SurahVerse(20, "وَجَاۤءَ مِنْ اَقْصَا الْمَدِيْنَةِ رَجُلٌ يَّسْعٰى قَالَ يٰقَوْمِ اتَّبِعُوا الْمُرْسَلِيْنَۙ", "Wa jā'a min aqshal-madīnati rajuluy yas'ā qāla yā qaumit-tabi'ul-mursalīn", "Datanglah seorang lelaki bergegas dari ujung kota menyeru kaumnya agar mengikuti para rasul."),
  SurahVerse(21, "اتَّبِعُوْا مَنْ لَّا يَسْـَٔلُكُمْ اَجْرًا وَّهُمْ مُّهْتَدُوْنَ", "Ittabi'ū mal lā yas'alukum ajraw wa hum muhtadūn", "Ikutilah orang-orang yang tidak meminta bayaran kepada kalian dan mereka mendapat petunjuk."),
  SurahVerse(22, "وَمَا لِيَ لَآ اَعْبُدُ الَّذِيْ فَطَرَنِيْ وَاِلَيْهِ تُرْجَعُوْنَ", "Wa mā liya lā a'budul-ladzī fatharanī wa ilaihi turja'ūn", "Mengapa aku tidak menyembah Tuhan yang menciptakanku dan kepada-Nya kalian semua dikembalikan?"),
  SurahVerse(23, "ءَاَتَّخِذُ مِنْ دُوْنِهٖٓ اٰلِهَةً اِنْ يُّرِدْنِ الرَّحْمٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّيْ شَفَاعَتُهُمْ شَيْـًٔا وَّلَا يُنْقِذُوْنِۚ", "A'attakhidzu min dūnihī ālihatan iy yuridnir-rahmānu bidhurril lā tughni 'annī syafā'atuhum syai'aw wa lā yunqidzūn", "Apakah aku akan menyembah sesembahan selain Dia yang tidak mampu menolong atau menyelamatkanku?"),
  SurahVerse(24, "اِنِّيْٓ اِذًا لَّفِيْ ضَلٰلٍ مُّبِيْنٍ", "Innī idzal lafī dhalālim mubīn", "Jika demikian, sungguh aku berada dalam kesesatan yang nyata."),
  SurahVerse(25, "اِنِّيْٓ اٰمَنْتُ بِرَبِّكُمْ فَاسْمَعُوْنِۗ", "Innī āmantu birabbikum fasma'ūn", "Sesungguhnya aku telah beriman kepada Tuhan kalian, maka dengarkanlah aku."),
  SurahVerse(26, "قِيْلَ ادْخُلِ الْجَنَّةَ ۗقَالَ يٰلَيْتَ قَوْمِيْ يَعْلَمُوْنَۙ", "Qīlad-khulil-jannah, qāla yā laita qaumī ya'lamūn", "Dikatakan kepadanya, masuklah ke surga. Ia berharap andai kaumnya mengetahui."),
  SurahVerse(27, "بِمَا غَفَرَ لِيْ رَبِّيْ وَجَعَلَنِيْ مِنَ الْمُكْرَمِيْنَ", "Bimā ghafara lī rabbī wa ja'alanī minal-mukramīn", "Betapa Tuhanku telah mengampuniku dan menjadikanku termasuk orang-orang yang dimuliakan."),
  SurahVerse(28, "وَمَآ اَنْزَلْنَا عَلٰى قَوْمِهٖ مِنْۢ بَعْدِهٖ مِنْ جُنْدٍ مِّنَ السَّمَاۤءِ وَمَا كُنَّا مُنْزِلِيْنَ", "Wa mā anzalnā 'alā qaumihī mim ba'dihī min jundim minas-samā'i wa mā kunnā munzilīn", "Setelah wafatnya, Kami tidak perlu menurunkan pasukan bala tentara dari langit kepada kaumnya."),
  SurahVerse(29, "اِنْ كَانَتْ اِلَّا صَيْحَةً وَّاحِدَةً فَاِذَا هُمْ خَامِدُوْنَ", "In kānat illā shaihataw wāhidatan fa'idzā hum khāmidūn", "Hanya dengan satu teriakan keras saja, seketika itu mereka langsung binasa."),
  SurahVerse(30, "يٰحَسْرَةً عَلَى الْعِبَادِۚ مَا يَأْتِيْهِمْ مِّنْ رَّسُوْلٍ اِلَّا كَانُوْا بِهٖ يَسْتَهْزِءُوْنَ", "Yā hasratan 'alal-'ibād, mā ya'tīhim mir rasūlin illā kānū bihī yastahzi'ūn", "Alangkah besar penyesalan bagi hamba-hamba yang selalu memperolok setiap rasul yang datang."),
  SurahVerse(31, "اَلَمْ يَرَوْا كَمْ اَهْلَكْنَا قَبْلَهُمْ مِّنَ الْقُرُوْنِ اَنَّهُمْ اِلَيْهِمْ لَا يَرْجِعُوْنَ", "Alam yarau kam ahlaknā qablahum minal-qurūni annahum ilaihim lā yarji'ūn", "Tidakkah mereka melihat betapa banyak generasi sebelum mereka yang dibinasakan dan tidak pernah kembali?"),
  SurahVerse(32, "وَاِنْ كُلٌّ لَّمَّا جَمِيْعٌ لَّدَيْنَا مُحْضَرُوْنَ", "Wa in kullul lammā jamī'ul ladainā muhdharūn", "Setiap makhluk semuanya pasti akan dihadapkan kepada Kami."),
  SurahVerse(33, "وَاٰيَةٌ لَّهُمُ الْاَرْضُ الْمَيْتَةُ ۖاَحْيَيْنٰهَا وَاَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُوْنَ", "Wa āyatul lahumul-ardhul-maitatu ahyaināhā wa akhrajnā minhā habban faminhu ya'kulūn", "Tanda kekuasaan Allah bagi mereka ialah tanah tandus yang Kami hidupkan dan tumbuhkan biji-bijian sebagai makanan."),
  SurahVerse(34, "وَجَعَلْنَا فِيْهَا جَنّٰتٍ مِّنْ نَّخِيْلٍ وَّاَعْنَابٍ وَّفَجَّرْنَا فِيْهَا مِنَ الْعُيُوْنِۙ", "Wa ja'alnā fīhā jannātim min nakhīliw wa a'nābiw wa fajjarnā fīhā minal-'uyūn", "Kami jadikan pula kebun kurma dan anggur serta Kami pancarkan mata air di dalamnya."),
  SurahVerse(35, "لِيَأْكُلُوْا مِنْ ثَمَرِهٖۙ وَمَا عَمِلَتْهُ اَيْدِيْهِمْ ۗ اَفَلَا يَشْكُرُوْنَ", "Liya'kulū min tsamarihī wa mā 'amilathu aidīhim, afalā yasykurūn", "Agar mereka dapat menikmati buah-buahan dan hasil usaha mereka, maka mengapa tidak bersyukur?"),
  SurahVerse(36, "سُبْحٰنَ الَّذِيْ خَلَقَ الْاَزْوَاجَ كُلَّهَا مِمَّا تُنْۢبِتُ الْاَرْضُ وَمِنْ اَنْفُسِهِمْ وَمِمَّا لَا يَعْلَمُوْنَ", "Subhānal-ladzī khalaqal-azwāja kullahā mimmā tumbitul-ardhu wa min anfusihim wa mimmā lā ya'lamūn", "Maha Suci Allah yang menciptakan segala sesuatu berpasang-pasangan dari tumbuhan, manusia, dan hal yang belum diketahui."),
  SurahVerse(37, "وَاٰيَةٌ لَّهُمُ الَّيْلُ ۖنَسْلَخُ مِنْهُ النَّهَارَ فَاِذَا هُمْ مُّظْلِمُوْنَۙ", "Wa āyatul lahumul-lailu naslakhu minhun-nahāra fa'idzā hum muzhlimūn", "Tanda lainnya adalah malam ketika Kami tanggalkan siang darinya sehingga manusia berada dalam kegelapan."),
  SurahVerse(38, "وَالشَّمْسُ تَجْرِيْ لِمُسْتَقَرٍّ لَّهَا ۗذٰلِكَ تَقْدِيْرُ الْعَزِيْزِ الْعَلِيْمِۗ", "Wasy-syamsu tajrī limustaqarril lahā, dzālika taqdīrul-'azīzil-'alīm", "Matahari beredar pada garis edarnya; itulah ketetapan Tuhan Yang Maha Perkasa lagi Maha Mengetahui."),
  SurahVerse(39, "وَالْقَمَرَ قَدَّرْنٰهُ مَنَازِلَ حَتّٰى عَادَ كَالْعُرْجُوْنِ الْقَدِيْمِ", "Wal-qamara qaddarnāhu manāzila hattā 'āda kal-'urjūnil-qadīm", "Bagi bulan telah Kami tetapkan fase-fase peredarannya hingga kembali berbentuk seperti tandan kering."),
  SurahVerse(40, "لَا الشَّمْسُ يَنْۢبَغِيْ لَهَآ اَنْ تُدْرِكَ الْقَمَرَ وَلَا الَّيْلُ سَابِقُ النَّهَارِ ۗوَكُلٌّ فِيْ فَلَكٍ يَّسْبَحُوْنَ", "Lasy-syamsu yambaghī lahā an tudrikal-qamara wa lal-lailu sābiqun-nahār, wa kullun fī falakiy yasbahūn", "Matahari tidak mungkin mengejar bulan dan malam pun tidak mendahului siang; masing-masing beredar pada orbitnya."),
  SurahVerse(41, "وَاٰيَةٌ لَّهُمْ اَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى الْفُلْكِ الْمَشْحُوْنِۙ", "Wa āyatul lahum annā hamalnā dzurriyyatahum fil-fulkil-masyhūn", "Tanda kebesaran Kami lainnya adalah ketika Kami angkut keturunan mereka di dalam bahtera yang sarat muatan."),
  SurahVerse(42, "وَخَلَقْنَا لَهُمْ مِّنْ مِّثْلِهٖ مَا يَرْكَبُوْنَ", "Wa khalaqnā lahum mim mitslihī mā yarkabūn", "Dan Kami ciptakan bagi mereka berbagai jenis kendaraan lain yang serupa untuk ditunggangi."),
)
